import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long p = scanner.nextLong();
        long d = scanner.nextLong();
        p++;
        long ans = p;
        for (long t = 10; ; t *= 10) {
            if (p % t > d) {
                break;
            }
            ans = p - p % t;
        }
        System.out.print(ans - 1);
    }
}

